function movement(){const m=new Movements(bot);m.canDig=false;m.canOpenDoors=false;m.allowSprinting=false;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=2;for(const n of['water','lava','fire','magma_block','sweet_berry_bush','nether_portal','powder_snow'])if(bot.registry.blocksByName[n])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);const hazard=b=>!b||/^(water|lava|fire|soul_fire|magma_block|cactus|powder_snow|nether_portal)$/.test(b.name);const safeCell=(x,y,z)=>{const f=bot.blockAt(new Vec3(x,y-1,z));return !hazard(f)&&f.boundingBox==='block'&&!hazard(bot.blockAt(new Vec3(x,y,z)))&&!hazard(bot.blockAt(new Vec3(x,y+1,z)));};const prior=m.getNeighbors.bind(m);m.getNeighbors=n=>prior(n).filter(v=>safeCell(v.x,v.y,v.z)&&(!(v.x!==n.x&&v.z!==n.z)||(safeCell(v.x,v.y,n.z)&&safeCell(n.x,v.y,v.z)))&&Math.abs(v.y-n.y)<=1&&!Object.values(bot.entities).some(e=>['skeleton','stray','witch','creeper','zombie','zombie_villager','spider','drowned'].includes(e.name)&&e.position.distanceTo(new Vec3(v.x+.5,v.y,v.z+.5))<(['skeleton','stray','witch'].includes(e.name)?16:e.name==='creeper'?9:6)&&exposedAt(e,new Vec3(v.x+.5,v.y,v.z+.5))));bot.pathfinder.setMovements(m);bot.pathfinder.thinkTimeout=1500;}
async function go(p,ms){movement();let timer,damaged=false;const hurt=e=>{if(e===bot.entity){damaged=true;bot.pathfinder.setGoal(null);}};bot.on('entityHurt',hurt);try{await Promise.race([bot.pathfinder.goto(new goals.GoalBlock(p.x,p.y,p.z)),new Promise((_,r)=>timer=setTimeout(()=>{bot.pathfinder.setGoal(null);r(Error('NAV_BOUND'));},ms))]);}finally{clearTimeout(timer);bot.removeListener('entityHurt',hurt);bot.pathfinder.setGoal(null);bot.clearControlStates();}await ticks(4);if(damaged||!bot.entity.onGround||!bot.entity.position.floored().equals(p))throw Error('NAV_NOT_ACTUAL');}








